class Mass:
    standard: int
    epsilon: int
    def __add__(self, other: "Mass") -> "Mass":
        return Mass(self.standard + other.standard, self.epsilon + other.epsilon)

def event_mass(cardinality: int, *, cofinite: bool) -> Mass:
    """Evaluate a finite event, or a cofinite event via complement cardinality."""
    if cardinality < 0:
        raise ValueError("cardinality must be nonnegative")
    return Mass(1, -cardinality) if cofinite else Mass(0, cardinality)

def mixed_disjoint_union(finite_size: int, missing_size: int) -> Mass:
    """Mass of F union (X \ M), assuming F is a subset of M."""
    if not 0 <= finite_size <= missing_size:
        raise ValueError("disjointness requires the finite event to lie in the missing set")
    return event_mass(missing_size - finite_size, cofinite=True)

